diagram.source:
flowchart TD
  START["Need to check value"] --> NULL{"x === null?"}
  NULL -->|yes| ISNULL["It's null"]
  NULL -->|no| PRIM{"typeof is primitive label?"}
  PRIM -->|string/number/etc| PRIMTYPE["Use typeof result"]
  PRIM -->|object| ARR{"Array.isArray(x)?"}
  ARR -->|yes| ISARR["It's an array"]
  ARR -->|no| INST["instanceof or toString brand"]

snippet.code:
function describe(value) {
  if (value === null) return 'null';
  if (value === undefined) return 'undefined';
  return typeof value;
}

console.log(typeof null);       // 'object' — bug
console.log(describe(null));    // 'null' — correct
console.log(describe(undefined)); // 'undefined'

const payload = { items: [1, 2], meta: null };

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

console.log(Array.isArray(payload.items)); // true
console.log(isPlainObject(payload));       // true
console.log(isPlainObject(payload.items)); // false
console.log(isPlainObject(payload.meta));  // false — null fails first check

const err = new TypeError('bad type');
console.log(err instanceof Error);     // true
console.log(err instanceof TypeError); // true

// In another iframe, Array might differ:
// iframeArray instanceof Array → false (different realm)
// Array.isArray(iframeArray) → true (spec-safe)

class MyError extends Error {}
const e = new MyError('oops');
console.log(e instanceof MyError); // true

// API returns null when user not found
const user = null;

if (typeof user === 'object') {
  // BUG: null enters here!
  console.log(user.name); // TypeError: Cannot read properties of null
}

// Fix:
if (user !== null && typeof user === 'object') {
  console.log(user.name);
}
